Here is the root cause:
The bug was caused by the failure to set unused color plane offsets to `~0xfff` when the number of potential color planes increased to 4. This inconsistency led to the `skl_check_main_surface()` function potentially using stale offsets, which could result in incorrect calculations of the main surface offset relative to the auxiliary surface offset, violating the requirement that the auxiliary distance (AUX_DIST) must be non-negative.

Here is the patch:

 int skl_check_plane_surface(struct intel_plane_state *plane_state)
 {
 	const struct drm_framebuffer *fb = plane_state->hw.fb;
-	int ret;
-	bool needs_aux = false;
+	int ret, i;

 	ret = intel_plane_compute_gtt(plane_state);
 	if (ret)
 		return ret;

 	if (!plane_state->uapi.visible)
 		return 0;

 	/*
 	 * Handle the AUX surface first since the main surface setup depends on
 	 * it.
 	 */
 	if (is_ccs_modifier(fb->modifier)) {
-		needs_aux = true;
 		ret = skl_check_ccs_aux_surface(plane_state);
 		if (ret)
 			return ret;
 	}

 	if (intel_format_info_is_yuv_semiplanar(fb->format,
 						fb->modifier)) {
-		needs_aux = true;
 		ret = skl_check_nv12_aux_surface(plane_state);
 		if (ret)
 			return ret;
 	}

-	if (!needs_aux) {
-		int i;
-
-		for (i = 1; i < fb->format->num_planes; i++) {
-			plane_state->color_plane[i].offset = ~0xfff;
-			plane_state->color_plane[i].x = 0;
-			plane_state->color_plane[i].y = 0;
-		}
+	for (i = fb->format->num_planes; i < ARRAY_SIZE(plane_state->color_plane); i++) {
+		plane_state->color_plane[i].offset = ~0xfff;
+		plane_state->color_plane[i].x = 0;
+		plane_state->color_plane[i].y = 0;
 	}

 	ret = skl_check_main_surface(plane_state);
 	if (ret)
 		return ret;

 	return 0;
 }



